public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int maxK = n / 2;
    // sumsBySize[k] holds all possible sums of subsets of size k
    List<Set<Long>> sumsBySize = new ArrayList<>(maxK + 1);
    for (int i = 0; i <= maxK; i++) {
        sumsBySize.add(new HashSet<>());
    }
    sumsBySize.get(0).add(0L);
    for (int num : nums) {
        // iterate sizes in reverse to avoid using the same element twice
        for (int size = maxK; size >= 1; size--) {
            Set<Long> prevSet = sumsBySize.get(size - 1);
            if (prevSet.isEmpty()) {
                continue;
            }
            Set<Long> currSet = sumsBySize.get(size);
            for (long s : prevSet) {
                currSet.add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long target = (totalSum * k) / n;
        if (sumsBySize.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) with no cost
        return 0;
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

