public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int total = 1 << k;
    if (s.length() < total) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) {
            return false;
        }
    }
    return true;
}

