public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;      // number of unmatched '('
    int insertions = 0;   // number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--;          // match with an existing '('
            } else {
                insertions++;        // need to insert a '(' before this ')'
                // balance remains 0 after this insertion
            }
        } else {
            // If the string may contain other characters, they are ignored.
            // Alternatively, you could throw an exception for invalid input.
        }
    }

    // Any remaining unmatched '(' need a ')' inserted after them
    return insertions + balance;
}

