public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;
    int currentMax = 0;
    int currentMin = 0;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);
        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[45]; // F(45) is the largest Fibonacci number <= 1e9
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    // Greedy subtraction from largest to smallest
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if c and top are the same letter with opposite cases
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c); // push current character onto the stack
    }
    return stack.toString();
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            depth = Math.max(0, depth - 1);
        } else if (log.equals("./")) {
            // stay in the current folder, no change
        } else {
            // any other string ending with '/' is considered a subfolder entry
            if (log.endsWith("/")) {
                depth++;
            }
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    // Minimum possible sum is n (all 'a'), maximum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    char[] result = new char[n];
    java.util.Arrays.fill(result, 'a');
    int remaining = k - n; // extra value needed beyond all 'a's
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add at most 25 to change 'a' to 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

