public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    int count = 0;
    for (int factor = 1; factor <= n; factor *= 10) {
        int lower = n % factor;
        int cur = (n / factor) % 10;
        int higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set.
    // Using the bitwise trick: n & (n - 1) will be zero only for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    // dp[i][j][d] where d: 0=horizontal, 1=vertical, 2=diagonal, 3=anti-diagonal
    int[][][] dp = new int[m][n][4];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;          // horizontal
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;          // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1; // diagonal
                dp[i][j][3] = (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0) + 1; // anti-diagonal
                int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                       Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long absValue = Math.abs((long) n); // use long to avoid overflow for Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (absValue > 0) {
        sb.append(absValue % 10);
        absValue /= 10;
        digitCount++;
        if (absValue > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int k = 0; k < m + n - 1; k++) {
        int startI = Math.min(k, m - 1);
        int endI = Math.max(0, k - (n - 1));
        int len = startI - endI + 1;
        int[] temp = new int[len];
        int tIdx = 0;
        int i = startI;
        int j = k - i;
        while (i >= endI && j < n) {
            temp[tIdx++] = mat[i][j];
            i--;
            j++;
        }
        if (k % 2 == 0) {
            for (int t = len - 1; t >= 0; t--) {
                result[idx++] = temp[t];
            }
        } else {
            for (int t = 0; t < len; t++) {
                result[idx++] = temp[t];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no higher permutation
    }
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        long result = Long.parseLong(new String(digits));
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) result;
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    char[] arr = new char[n];
    backtrack(0, n - 1, arr, pairs, result);
    return result;
}

private static void backtrack(int left, int right, char[] arr, char[][] pairs, List<String> result) {
    if (left > right) {
        result.add(new String(arr));
        return;
    }
    if (left == right) {
        // middle digit for odd length
        for (char c : new char[]{'0','1','8'}) {
            arr[left] = c;
            result.add(new String(arr));
        }
        return;
    }
    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0') {
            continue; // no leading zero for length > 1
        }
        arr[left] = pair[0];
        arr[right] = pair[1];
        backtrack(left + 1, right - 1, arr, pairs, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if ((long) current * 10 <= n) {
            current *= 10;
        } else {
            if (current % 10 != 9 && current + 1 <= n) {
                current++;
            } else {
                while (current % 10 == 9) {
                    current /= 10;
                }
                current = current / 10 + 1;
            }
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) == ' ') {
            // Preserve spaces
            result.append(' ');
            i++;
        } else {
            // Find the end of the current word
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            // Reverse the word from start to i-1
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}
